def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 45.0))
        return float(min(budget, 18.0))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        if opp.get('budget', 0) >= 700:
            rich_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    my_urgent = 0
    if hp <= 2:
        my_urgent += 2
    elif hp <= 4:
        my_urgent += 1
    if no_water_days >= 1:
        my_urgent += 2

    if my_urgent >= 3:
        target = max(95.0, highest_prev + 4.0)
        if rich_opp >= 1:
            target += 8.0
        if supply <= 17:
            target += 10.0
        return float(min(budget, min(150.0, target)))

    if my_urgent == 2:
        target = max(72.0, avg_prev * 0.72, highest_prev * 0.62)
        target += scarcity * 18.0
        if urgent_opp >= 2:
            target += 8.0
        return float(min(budget, min(120.0, target)))

    if supply >= 22 and hp >= 6 and no_water_days == 0:
        target = 16.0
        if highest_prev < 80:
            target = 22.0
        return float(min(budget, target))

    if supply <= 17:
        target = max(48.0, highest_prev * 0.42)
        if urgent_opp >= 1:
            target += 6.0
        if rich_opp >= 2:
            target += 6.0
        return float(min(budget, min(78.0, target)))

    target = max(28.0, avg_prev * 0.3)
    target += scarcity * 10.0
    if hp <= 5:
        target += 8.0
    return float(min(budget, min(65.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Yesterday trace reaction: infer aggressiveness.
    # We only use previous_trace from each opponent.
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base bid derived from supply pressure.
    # If supply is near minimum, competition likely matters more.
    # Map supply in [15,25] to a multiplier in [0.65,1.0]
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_mult = 1.0
    else:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if t < 0.0:
            t = 0.0
        if t > 1.0:
            t = 1.0
        supply_mult = 0.65 + 0.35 * t

    # Target bid budget fraction: moderate by default.
    # Increase if our hp/no_water_days are critical.
    if hp <= 1.5 or no_water_days >= 2:
        frac = 0.85
    elif hp <= 3.0 or no_water_days >= 1:
        frac = 0.65
    else:
        frac = 0.45

    # If someone was extremely aggressive yesterday, we slightly raise to avoid being starved.
    # Cindy-like behavior corresponds to very high previous bids.
    if highest_prev_bid >= DAILY_SALARY * 1.4:
        frac = max(frac, 0.60)
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        frac = max(frac, 0.52)

    bid = budget * frac

    # Add a small supply-scaled floor to ensure we participate when supply is tight.
    # Use int() indices only where needed; none here.
    floor_bid = DAILY_SALARY * 0.35 * supply_mult
    if bid < floor_bid:
        bid = floor_bid

    # Cap: never exceed what we can spend.
    if bid > budget:
        bid = budget

    # Also avoid overbidding beyond a reasonable ceiling.
    ceiling = DAILY_SALARY * 0.95
    if bid > ceiling:
        bid = ceiling

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

